data.internal_stylesheets:
/* ====================== Branding ====================== */
/*
  #3366cc - blue
  #666666 - gray
  #a1a1a1 - gray light
*/

:root {
    --cc-color-primary: #3366cc;
    --cc-color-white: #fff;
    --cc-color-gray: #666666;
    --cc-color-gray-light: #a1a1a1;
    --cc-color-link: #666666;

    --cc-primary-ring: var(--cc-color-white) 0px 0px 0px 2px, var(--cc-color-gray) 0px 0px 0px 5px, rgba(0, 0, 0, 0.05) 0px 1px 2px 0px;
}

/* Accept all buttons - colors */
#c-p-bn, #s-all-bn {
    background: var( --cc-color-primary) !important;
    color: var(--cc-color-white) !important;
}

#c-p-bn:focus, #s-all-bn:focus {
    outline: none !important;
    box-shadow: var(--cc-primary-ring) !important;
}

/* Accept necessary buttons - colors */
#c-s-bn, #s-rall-bn {
    background: var(--cc-color-white) !important;
    color: var( --cc-color-primary) !important;
}

/* Third button - open settings & save preferences - colors */
#c-t-bn, #s-sv-bn {
    background: var(--cc-color-white) !important;
    color: var( --cc-color-primary) !important;
}

#c-s-bn:focus, #s-rall-bn:focus, #c-t-bn:focus, #s-sv-bn:focus {
    box-shadow: var(--cc-primary-ring) !important;
}

/* Consent & Settings modal - text color, box shadow */
#cm, #s-inr {
    box-shadow: 0 20px 40px rgba(0,0,0,.4) !important;
    color: #000000 !important;
}

/* Settings modal - checked toggle buttons */
.cc_div .b-tg .c-tgl:checked~.c-tg {
    background: var( --cc-color-primary);
}

/* Settings modal - "Always active" text color */
#s-cnt .b-bn .b-tl .cc-always-active {
    color: var( --cc-color-primary);
}

/* Links (GDPR etc.) - color and underline color */
.cc_div .cc-link {
    color: var(--cc-color-gray-light);
    border-color: var(--cc-color-gray-light);
}

.cc_div .cc-link:focus {
    outline: none !important;
    box-shadow: var(--cc-primary-ring) !important;
}

/* ====================== UX ====================== */

.cc_div *, .cc_div :after, .cc_div :before, .cc_div :hover {
    line-height: 1.3em;
}

/* Overlay */
#cm-ov, #cs-ov {
    background: transparent;
}

.force--consent #cm-ov {
    background: rgba(4,6,8, 0.6);
}

/* Consent modal */
#cm {
    font-family: "Open Sans", Arial, Helvetica, sans-serif !important; /* Todo: move to one place */
    max-width: 550px;
    max-height: initial;
    padding: 76px 103px;
    overflow-y: auto;
    border-radius: 0;
}

#c-inr {
    display: flex;
    flex-direction: column;
    height: 100%;
    max-height: 70vh;
}

#c-inr-i {
    flex: 1 1 auto;
    overflow-y: auto;
    padding: 0 6px;
    margin: 0 -6px;
}

#c-ttl {
    position: fixed;
    background: var(--cc-color-white);
    width: calc(100% - 103px);
    padding-bottom: 8px;
    margin-bottom: 0;
    font-size: 18px;
}

#c-txt {
    font-size: 16px;
    line-height: 1.3em;
    padding-top: 28px;
    padding-bottom: 5px;
}

/* Settings modal */
#c-s-in {
    font-family: "Open Sans", Arial, Helvetica, sans-serif !important; /* Todo: move to one place */
    max-height: initial;
    height: 100%;
    transform: none;
    top: 0;
    position: relative;
    overflow-y: auto;
}

#s-inr {
    display: flex;
    position: fixed;
    transform: none !important;
    top: auto !important;
    bottom: 20px;
    left: 0;
    right: 0;
    overflow-y: auto;
    height: auto;
    max-height: 90vh;
    max-width: 550px;
    padding: 76px 103px;
    border-radius: 0;
    flex-direction: column;
}

#s-cnt .p {
    margin-top: 8px;
    font-size: 16px;
    line-height: 1.3em;
    color: inherit;
}

#s-bl {
    height: auto;
    flex: 1 1 auto;
    overflow-y: auto;
    padding: 0 6px;
    margin: 0 -6px;
}

#s-bl .b-tl {
    font-size: 18px;
}

#s-bl .c-bl {
    border: 0
}

#s-bl .c-bl:first-child {
    padding-top: 72px !important;
}

#s-bl .c-bl:last-child {
    margin-top: 2em;
    padding: 0;
    text-align: center;
}

#s-bl .c-bl:last-child .p {
    text-align: center;
    color: var(--cc-color-gray-light);
    font-size: 14px;
}

#s-bl .c-bl:hover {
    background: inherit;
}

#s-bl .c-bl:first-child > .title {
    position: absolute;
    background: var(--cc-color-white);
    width: calc(100% - 103px);
    padding-bottom: 8px;
    top: 74px;
    z-index: 200;
}

#s-c-bnc {
    text-align: right;
}

#s-hdr {
    display: none;
}

/* Consent & Settings modal - window < 688px */
@media screen and (max-width: 688px) {
    #cc--main, #s-cnt, #cs {
        position: sticky !important;
    }

    #cm, #s-inr {
        position: fixed !important;
        bottom: 0 !important;
        left: 0 !important;
        right: 0 !important;
        top: auto !important;
        max-width: 100% !important;
        width: 100% !important;
        transform: translateZ(0) translateY(0) translateX(0) scale(1) !important;
        padding: 24px 16px 20px 16px !important;
    }

    #c-ttl {
        width: calc(100% - 16px);
    }

    .bns-t #s-bns {
        height: auto !important;
    }

    #s-bl .c-bl:first-child > .title {
        top: 22px;
        width: 100%;
    }

    .cc_div .bns-t .c-bn {
        font-size: 16px !important;
    }
}

/* Settings modal - accordions */
#s-bl .c-bl.b-ex {
    background: inherit;
    padding: 0;
    margin-bottom: 4px;
}

#s-cnt .b-bn .b-tl {
    display: flex;
    align-items: center;
    justify-content: flex-start;
    padding: 9px 0;
    border-radius: 0;
}

#s-cnt .b-bn .b-tl:active, #s-cnt .b-bn .b-tl:hover {
    background: inherit;
}

#s-cnt .b-bn .b-tl:focus, #s-cnt .b-bn .b-tl:focus-visible {
    outline: none !important;
    box-shadow: var(--cc-primary-ring) !important;
}

#s-bl .b-acc .p {
    padding: 15px 0 25px 0;
}

/* Settings modal - accordions - carets */
.cc_div .act .b-bn .b-tl.exp::before, .cc_div .b-bn .b-tl.exp::before {
    border: none;
    padding: 0;
    position: static;
    transform: none;
    margin-right: 13px;
    width: 16px;
    height: 16px;
    background-image: url("data:image/svg+xml,%3Csvg width='12' height='6' viewBox='0 0 12 6' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath fill-rule='evenodd' clip-rule='evenodd' d='M10.291 1.70743C10.9214 1.07759 10.4754 0 9.58425 0H2.41268C1.52199 0 1.07572 1.07669 1.70525 1.70679L5.28781 5.29257C5.67815 5.68327 6.31132 5.68356 6.70202 5.29321L10.291 1.70743Z' fill='black'/%3E%3C/svg%3E%0A");
    background-size: auto;
    background-repeat: no-repeat;
    background-position: center center;
}

.cc_div .b-bn .b-tl.exp::before {
    transform: none;
    background-image: url("data:image/svg+xml,%3Csvg width='6' height='12' viewBox='0 0 6 12' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath fill-rule='evenodd' clip-rule='evenodd' d='M1.70743 1.70896C1.07759 1.07856 0 1.52463 0 2.41575L0 9.58732C0 10.478 1.07669 10.9243 1.70679 10.2947L5.29257 6.71219C5.68327 6.32185 5.68356 5.68868 5.29321 5.29798L1.70743 1.70896Z' fill='black'/%3E%3C/svg%3E%0A");
}

/* Settings modal - accordions - toggle (times, checks, hidden readonly) */
.cc_div .off-i::after, .cc_div .off-i::before {
    content: none;
}

.cc_div .on-i::before {
    content: none;
}

.cc_div .b-tg {
    right: 8px;
}

.cc_div .b-tg, .cc_div .b-tg .c-tg, .cc_div .b-tg .c-tgl, .cc_div span.t-lb {
    width: 56px;
    height: 32px;
    border-radius: 16px;
}

.cc_div .b-tg .c-tg:after {
    left: 4px;
    top: 50%;
    transform: translateY(-50%);
    width: 24px;
    height: 24px;
}

.cc_div .b-tg .c-tgl:checked~.c-tg:after {
    transform: translateY(-50%) translateX(100%);
}

.cc_div .b-tg input[value="functionality_storage"]:disabled,
.cc_div .b-tg input[value="functionality_storage"]:disabled ~ .c-tg.c-ro {
    display: none;
}

.cc_div .b-tg .c-tgl:disabled {
    cursor: default;
}

#s-cnt .b-bn .b-tl .cc-always-active {
    position: absolute;
    right: 8px;
}

.cc_div .b-tg .c-tgl:focus, .cc_div .b-tg .c-tgl:focus-visible {
    outline: none !important;
    box-shadow: var(--cc-primary-ring) !important;
}

/* Modals - Buttons */
.cc_div .c-bn {
    display: flex;
    align-items: center;
    justify-content: center;
    outline: 0 !important;
    border-radius: 0 !important;
    padding: 15px !important;
    font-size: 16px;
    font-weight: normal;
}

.cc_div .c-bn:hover {
    opacity: 0.9;
}

