.cc_div .c-bn svg {
    margin-right: 10px;
}

.cc_div #c-bns {
    flex-direction: column;
    margin-top: 20px;
}

#c-bns button+button, #s-c-bn, #s-cnt button+button {
    float: none;
    margin: 7px 0 0 0;
}

#s-bns {
    height: auto;
    display: flex;
    flex-direction: column;
    position: static;
    border-top: none;
    padding: 10px 0 0 0;
}

/* Order of buttons in the settings modal */
#s-rall-bn {
    order: 3;
}

#s-sv-bn {
    order: 2;
}

/* Modals - links */
.cc_div .cc-link {
    white-space: nowrap;
}

.cc_div .cc-link-box {
    margin-top: 25px;
}

.cc_div .cc-link-box .cc-link {
    display: inline-block;
}

.cc_div .cc-link-box .cc-link:not(:last-child) {
    margin-right: 20px;
}

/* Back button */
.cc_div a.cc-back-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: 20px;
    margin-bottom: 30px;
    font-size: 16px;
    text-decoration: none;
    border-bottom: 0;
    color: var(--cc-color-link);
}

.cc_div a.cc-back-button:hover {
    color: var(--cc-color-link);
}

.cc_div a.cc-back-button:hover span {
    border-bottom: 1px solid transparent;
}

.cc_div a.cc-back-button:before {
    content: '';
    display: inline-block;
    width: 18px;
    height: 18px;
    margin-right: 8px;
    background-image: url("data:image/svg+xml,%3Csvg width='18' height='16' viewBox='0 0 18 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M8 1L1 8L8 15' stroke='%23666666' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3Cpath d='M1 8H17' stroke='%23666666' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E%0A");
    background-size: contain;
    background-repeat: no-repeat;
}

.cc_div a.cc-back-button span {
    border-bottom: 1px solid var(--cc-color-link);
}

.cc_div a.cc-back-button:focus {
    outline: none !important;
    box-shadow: var(--cc-primary-ring) !important;
}

/* Description block in the Settings modal */
.cc_div .cc-description-block {
    border-left: 1px solid var(--cc-color-gray-light);
    padding-left: 15px;
    margin-top: 24px;
}

.cc_div .cc-description-block + .cc-description-block {
    padding-top: 12px;
    margin-top: 0;
}

.cc_div .cc-description-block strong {
    font-weight: bold;
}

/* Cookie table */
#s-bl table,
#s-bl table tbody,
#s-bl table tr,
#s-bl table th,
#s-bl table td {
    display: block !important;
}

#s-bl table thead {
    display: none;
}

#s-bl table tbody td,
#s-bl table tbody th {
    padding: 8px 0 8px 120px;
    position: relative;
}

#s-bl table tbody td::before,
#s-bl table tbody th::before {
    content: attr(data-column);
    position: absolute;
    left: 0;
    top: 8px;
    width: 110px;
    font-weight: bold;
    word-break: break-word;
}

#s-bl table tbody tr {
    padding: 16px 0;
    border-bottom: 1px solid var(--cc-color-gray-light) !important;
}

#s-bl table tbody tr:first-child {
    border-top: 1px solid var(--cc-color-gray-light) !important;
}

#s-bl table tbody tr:hover {
    background: inherit !important;
}

#s-bl table tbody tr td a {
    white-space: nowrap !important;
    text-decoration: none !important;
    color: var(--cc-color-link) !important;
    border: 0 !important;
}

#cm-ov, #cs-ov, .c--anim #cm, .c--anim #s-cnt, .c--anim #s-inr {
    transition: visibility .25s linear, opacity .25s ease, transform .25s ease, box-shadow .25s ease !important;
}

.show--settings #cm {
    box-shadow: none !important;
}
